      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-baton-mcp\",\n  \"version\": \"0.6.13\",\n  \"mcpName\": \"io.github.JialaoLiu/dsh-baton\",\n  \"description\": \"Pass the baton from Claude Code, Codex or any MCP client to a local DeepSeek Harness: an MCP server that hands off tasks, continues a specific session, shows the run live in Harness and hands the result back when it is done.\",\n  \"type\": \"module\",\n  \"bin\": {\n    \"dsh-baton\": \"src/cli.mjs\",\n    \"dsh-baton-mcp\": \"src/bin.mjs\"\n  },\n  \"files\": [\n    \"src\",\n    \"host/lib\",\n    \"host/package.json\",\n    \"host/cordis.patch.yml\",\n    \"host/README.md\",\n    \"host/LICENSE\",\n    \"patches\",\n    \"README.md\",\n    \"README.zh-CN.md\",\n    \"WINDOWS.md\",\n    \"LICENSE\",\n    \"server.json\"\n  ],\n  \"engines\": {\n    \"node\": \">=22.15\"\n  },\n  \"keywords\": [\n    \"mcp\",\n    \"deepseek\",\n    \"deepseek-harness\",\n    \"claude-code\",\n    \"codex\",\n    \"multi-agent\",\n    \"orchestration\"\n  ],\n  \"license\": \"MIT\",\n  \"scripts\": {\n    \"test\": \"node --test --test-concurrency=1 tests/*.test.mjs\",\n    \"test:live\": \"node tests/live.mjs\",\n    \"prepublishOnly\": \"node scripts/version.mjs\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/JialaoLiu/dsh-baton.git\"\n  },\n  \"homepage\": \"https://github.com/JialaoLiu/dsh-baton#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/JialaoLiu/dsh-baton/issues\"\n  }\n}\n"
