      "path": "src/core.mjs",
      "content": "// Core logic shared by the MCP server and the CLI: locating DeepSeek Harness,\n// reading its saved sessions, and running headless turns as detached background runs.\nimport fs from 'node:fs'\nimport os from 'node:os'\nimport path from 'node:path'\nimport zlib from 'node:zlib'\nimport crypto from 'node:crypto'\nimport net from 'node:net'\nimport { spawn, execFileSync } from 'node:child_process'\nimport { fileURLToPath } from 'node:url'\nimport { setting, batonHome, socketEndpoint, hostEndpoints } from '../host/lib/socket.js'\nimport * as evidence from './evidence.mjs'\n\nconst HERE = path.dirname(fileURLToPath(import.meta.url))\nexport const ROOT = path.resolve(HERE, '..')\n\nconst MAC_DSH = '/Applications/DeepSeek Harness.app/Contents/Resources/runtime/cli/bin/dsh'\n\nexport const config = {\n  dshHome: process.env.DSH_HOME || path.join(os.homedir(), '.dsh'),\n  batonHome: batonHome(),\n  // Extra --patch overlays, separated by the platform path delimiter.\n  extraPatches: (setting('PATCHES') || '').split(path.delimiter).filter(Boolean),\n  // Set DSH_BATON_ACCOUNT=0 to use the API-key route instead of the desktop account sign-in.\n  useAccount: setting('ACCOUNT') !== '0',\n}\n\nconst IS_WIN = process.platform === 'win32'\n\n// The Windows desktop app has no standalone dsh launcher: its CLI is a script\n// packed in app.asar, run by the app's own Electron binary in Node mode.\n// It installs per user into %LOCALAPPDATA%\\Programs by default, but the folder\n// can be chosen at install time, so the uninstall entries are read as well.\nfunction winHarnessExe() {\n  const dirs = [path.join(process.env.LOCALAPPDATA || path.join(os.homedir(), 'AppData', 'Local'), 'Programs', 'DeepSeek Harness')]\n  for (const hive of ['HKCU', 'HKLM']) {\n    try {\n      const out = execFileSync('reg', ['query', `${hive}\\\\Software\\\\Microsoft\\\\Windows\\\\CurrentVersion\\\\Uninstall`, '/s', '/v', 'InstallLocation'], { windowsHide: true, stdio: ['ignore', 'pipe', 'ignore'] }).toString()\n      for (const m of out.matchAll(/InstallLocation\\s+REG_\\w+\\s+(.+)/g)) dirs.push(m[1].trim().replace(/^\"|\"$/g, ''))\n    } catch { /* no such key */ }\n  }\n  return dirs.map((d) => path.join(d, 'DeepSeek Harness.exe')).find((exe) => fs.existsSync(exe))\n}\nconst WIN_DSH_SCRIPT = ['resources', 'app.asar', 'dsh', 'node_modules', '@deepseek-ai', 'dsh', 'lib', 'bin.js']\nconst WIN_DSH_LAUNCHER = ['resources', 'runtime', 'cli', 'bin', 'dsh.cmd']\n\nexport function dshBin() {\n  if (process.env.DSH_BIN) return process.env.DSH_BIN\n  if (fs.existsSync(MAC_DSH)) return MAC_DSH\n  try {\n    const hits = execFileSync(IS_WIN ? 'where' : 'which', ['dsh'], { windowsHide: true, stdio: ['ignore', 'pipe', 'ignore'] }).toString().split(/\\r?\\n/).map((l) => l.trim()).filter(Boolean)\n    // `where` also lists extensionless shell shims that Windows cannot start; prefer a runnable one.\n    const hit = (IS_WIN && hits.find((h) => /\\.(exe|cmd|bat)$/i.test(h))) || hits[0]\n    if (hit) return hit\n  } catch { /* not on PATH */ }\n  const exe = IS_WIN && winHarnessExe()\n  if (exe) {\n    // Harness ≥ 0.2.1 ships its own launcher (the one its \"add dsh to PATH\" setting\n    // exposes); older builds only have the CLI packed in app.asar.\n    const launcher = path.join(path.dirname(exe), ...WIN_DSH_LAUNCHER)\n    return fs.existsSync(launcher) ? launcher : exe\n  }\n  throw new Error('DeepSeek Harness CLI not found. Install DeepSeek Harness or set DSH_BIN to the dsh launcher.')\n}\n\n// How to start dsh with these arguments: { file, args, options }. On Windows a\n// .cmd/.bat launcher needs cmd.exe (Node refuses to spawn it directly), and the\n// desktop app's own exe runs the packed CLI script with ELECTRON_RUN_AS_NODE=1.\nexport function dshCommand(args, bin = dshBin(), platform = process.platform) {\n  if (platform !== 'win32') return { file: bin, args, options: {} }\n  if (/\\.(cmd|bat)$/i.test(bin)) {\n    const quote = (a) => (/[\\s\"&|<>^()%!]/.test(a) || a === '' ? `\"${a.replace(/\"/g, '\"\"')}\"` : a)\n    const line = [bin, ...args].map(quote).join(' ')\n    return { file: process.env.ComSpec || 'cmd.exe', args: ['/d', '/s', '/c', `\"${line}\"`], options: { windowsVerbatimArguments: true } }\n  }\n  if (/DeepSeek Harness\\.exe$/i.test(bin)) {\n    return { file: bin, args: [path.join(path.dirname(bin), ...WIN_DSH_SCRIPT), ...args], options: { env: { ...process.env, ELECTRON_RUN_AS_NODE: '1' } } }\n  }\n  return { file: bin, args, options: {} }\n}\n\n// Stop a process. On Windows the dsh we started may be cmd.exe or Electron with\n// children of its own, so the whole tree of that one pid is ended.\nfunction stopProcess(pid) {\n  if (!IS_WIN) return process.kill(pid, 'SIGTERM')\n  execFileSync('taskkill', ['/PID', String(pid), '/T', '/F'], { stdio: 'ignore', windowsHide: true })\n}\n\n// Expand `~`, resolve, and follow symlinks when the path exists, so the same\n// folder always compares equal (on macOS /tmp is a link to /private/tmp).\nexport function normalizePath(p) {\n  const abs = path.resolve(p.replace(/^~(?=$|[\\\\/])/, os.homedir()))\n  try { return fs.realpathSync.native(abs) } catch { return abs }\n}\n\nfunction patchArgs() {\n  const patches = []\n  if (config.useAccount) patches.push(path.join(ROOT, 'patches', 'account.patch.yml'))\n  patches.push(...config.extraPatches)\n  return patches.flatMap((p) => ['--patch', p])\n}\n\n// ---------------------------------------------------------------------------\n// Host plugin (dsh-baton-host) running inside the Harness desktop app / `dsh web`.\n// Preferred backend: prompts go through the host's own session controller, so\n// they work on any session and show up live in the Harness UI.\n\n// The socket helpers are shared with the host plugin, so the two always agree.\nexport { socketEndpoint, setting }\nexport const hostSocket = () => hostEndpoints()[0]\n\n// Tries each endpoint in turn: a host plugin from before the rename listens on the old\n// pipe name on Windows until Harness restarts.\nexport async function hostCall(method, params, options) {\n  const endpoints = hostEndpoints()\n  for (let i = 0; ; i++) {\n    try {\n      return await hostCallAt(endpoints[i], method, params, options)\n    } catch (e) {\n      if (!e.hostDown || i === endpoints.length - 1) throw e\n    }\n  }\n}\n\nfunction hostCallAt(endpoint, method, params = {}, { timeoutMs = 15000 } = {}) {\n  return new Promise((resolve, reject) => {\n    const conn = net.connect(endpoint)\n    let buf = ''\n    let settled = false\n    const finish = (error, value) => {\n      if (settled) return\n      settled = true\n      clearTimeout(timer)\n      conn.destroy()\n      error ? reject(error) : resolve(value)\n    }\n    const timer = timeoutMs ? setTimeout(() => finish(new Error(`dsh-baton-host did not answer ${method} in time`)), timeoutMs) : null\n    conn.setEncoding('utf8')\n    conn.on('connect', () => conn.write(JSON.stringify({ id: 1, method, params }) + '\\n'))\n    conn.on('data', (chunk) => {\n      buf += chunk\n      const nl = buf.indexOf('\\n')\n      if (nl === -1) return\n      let msg\n      try { msg = JSON.parse(buf.slice(0, nl)) } catch { msg = null }\n      if (msg === null || typeof msg !== 'object' || Array.isArray(msg)) return finish(new Error(`dsh-baton-host sent an unreadable reply to ${method}`))\n      msg.error ? finish(new Error(String(msg.error))) : finish(null, msg.result)\n    })\n    conn.on('error', (e) => finish(Object.assign(e, { hostDown: true })))\n    // Harness quitting closes the connection mid-call: marked so a wait can wait for it to come back.\n    conn.on('close', () => finish(Object.assign(new Error(`dsh-baton-host closed the connection before answering ${method}`), { hostClosed: true })))\n  })\n}\n\nexport const VERSION = JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8')).version\n\n// The plugin version from the last successful ping.\nlet hostVersion = null\nlet hostFeatures = []\n\nexport async function hostAvailable() {\n  try {\n    const pong = await hostCall('ping', {}, { timeoutMs: 2000 })\n    hostVersion = pong?.version ?? null\n    hostFeatures = Array.isArray(pong?.features) ? pong.features : []\n    return true\n  } catch {\n    return false\n  }\n}\n\nexport const hostVersionSeen = () => hostVersion\n\n// The plugin and the MCP server update separately (Harness and npx), so they can drift.\n// A different major.minor gets a note asking to update the older side to the newer side's\n// exact version; patch releases mix. Not @latest: on a pre-release that would go back a version\n// (and Harness resolves a tag such as @next to a broken tarball, so the plugin needs the number).\nconst minorOf = (v) => String(v).split('.').slice(0, 2).join('.')\nconst parts = (v) => String(v).split('-')[0].split('.').map(Number)\nconst older = (a, b) => { const x = parts(a), y = parts(b); for (let i = 0; i < 3; i++) if (x[i] !== y[i]) return x[i] < y[i]; return false }\nexport function versionWarning(plugin = hostVersion, server = VERSION) {\n  if (!plugin || minorOf(plugin) === minorOf(server)) return null\n  const fix = older(plugin, server)\n    ? `Update the plugin in Harness: Plugins → dsh-baton-host → Uninstall, then Add plugin → dsh-baton-host@${server}.`\n    : `Update the server: \\`npx -y dsh-baton-mcp@${plugin} setup\\`.`\n  return `The Harness plugin dsh-baton-host is ${plugin} but this MCP server is ${server}. ${fix}`\n}\n\n// Who a relayed message is from, shown on it in the Harness chat: DSH_BATON_SENDER if set,\n// else the MCP client's name (claude-code, claude-ai → claude; codex-mcp-client → codex).\nexport function senderOf(clientName = setting('SENDER')) {\n  const n = String(clientName ?? '').toLowerCase()\n  if (n.includes('claude')) return 'claude'\n  if (n.includes('codex')) return 'codex'\n  const slug = n.replace(/[^a-z0-9-]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 32)\n  return slug || undefined\n}\n\nexport const isHostRun = (runId) => typeof runId === 'string' && runId.startsWith('hrun-')\n\n// ---------------------------------------------------------------------------\n// Sessions (headless fallback: read straight from ~/.dsh/sessions)\n\nconst ZSTD_MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd])\n\n// A session file is a sequence of appended zstd frames, each holding JSONL records.\n// maxBytes stops decoding early once enough text is read (for cheap listing).\nfunction readSessionRecords(file, maxBytes = Infinity) {\n  const buf = fs.readFileSync(file)\n  const starts = []\n  for (let i = buf.indexOf(ZSTD_MAGIC); i !== -1; i = buf.indexOf(ZSTD_MAGIC, i + 1)) starts.push(i)\n  const records = []\n  let text = ''\n  // The magic bytes can also occur inside compressed data. A frame cut at such a\n  // false start fails to decode, so extend it to the next candidate start until it\n  // decodes; a start that never decodes is itself a false start and is skipped.\n  let k = 0\n  while (k < starts.length && text.length <= maxBytes) {\n    let next = k + 1\n    for (let j = k + 1; j <= starts.length; j++) {\n      try {\n        text += zlib.zstdDecompressSync(buf.subarray(starts[k], starts[j] ?? buf.length)).toString()\n        next = j\n        break\n      } catch { /* cut inside this frame; try the next candidate end */ }\n    }\n    k = next\n  }\n  for (const line of text.split('\\n')) {\n    if (!line) continue\n    try { records.push(JSON.parse(line)) } catch { /* partial line */ }\n  }\n  return records\n}\n\nfunction sessionsRoot() {\n  return path.join(config.dshHome, 'sessions')\n}\n\nfunction sessionFile(dir) {\n  return path.join(dir, 'session.v4.jsonl.zstd')\n}\n\n// Every session directory, newest first.\nfunction allSessionDirs() {\n  const root = sessionsRoot()\n  if (!fs.existsSync(root)) return []\n  const out = []\n  for (const ws of fs.readdirSync(root)) {\n    const wsDir = path.join(root, ws)\n    let entries\n    try { entries = fs.readdirSync(wsDir) } catch { continue }\n    for (const id of entries) {\n      const file = sessionFile(path.join(wsDir, id))\n      try { out.push({ id, dir: path.join(wsDir, id), mtime: fs.statSync(file).mtimeMs }) } catch { /* not a session */ }\n    }\n  }\n  return out.sort((a, b) => b.mtime - a.mtime)\n}\n\nfunction findSessionDir(sessionId) {\n  const hit = allSessionDirs().find((s) => s.id === sessionId)\n  if (!hit) throw new Error(`Unknown session: ${sessionId}`)\n  return hit\n}\n\nfunction summarize(records, fallbackId) {\n  const header = records.find((r) => r.type === 'session') || {}\n  let title = null\n  for (const r of records) if (r.type === 'session/title') title = r.data?.title ?? title\n  return { session_id: header.id || fallbackId, cwd: header.cwd || null, title, created_at: header.createdAt ? new Date(header.createdAt).toISOString() : null }\n}\n\nexport function listSessions({ cwd, query, limit = 20 } = {}) {\n  const want = cwd ? normalizePath(cwd) : null\n  const q = query ? query.toLowerCase() : null\n  const out = []\n  for (const s of allSessionDirs()) {\n    if (out.length >= limit) break\n    let info\n    try { info = summarize(readSessionRecords(sessionFile(s.dir), 256 * 1024), s.id) } catch { continue }\n    if (want && (!info.cwd || normalizePath(info.cwd) !== want)) continue\n    if (q && !`${info.title ?? ''} ${info.cwd ?? ''} ${info.session_id}`.toLowerCase().includes(q)) continue\n    out.push({ ...info, updated_at: new Date(s.mtime).toISOString(), busy: activeRunFor(info.session_id)?.run_id ?? null })\n  }\n  return out\n}\n\nfunction textOf(content) {\n  if (!Array.isArray(content)) return ''\n  return content.filter((c) => c.type === 'text').map((c) => c.text).join('\\n')\n}\n\n// The visible conversation: user prompts and assistant replies, oldest first.\nexport function readSession({ session_id, last = 10 }) {\n  const s = findSessionDir(session_id)\n  const records = readSessionRecords(sessionFile(s.dir))\n  const messages = []\n  for (const r of records) {\n    if (r.type === 'user/message' && r.data?.source?.kind === 'user') {\n      messages.push({ role: 'user', time: new Date(r.time).toISOString(), text: textOf(r.data.content) })\n    } else if (r.type === 'assistant/message') {\n      const content = r.data?.message?.content || []\n      const tools = content.filter((c) => c.type !== 'text' && c.type !== 'reasoning').map((c) => c.name || c.type)\n      const text = textOf(content)\n      if (text || tools.length) messages.push({ role: 'assistant', time: new Date(r.time).toISOString(), text, ...(tools.length ? { tools } : {}) })\n    }\n  }\n  return { ...summarize(records, s.id), total_messages: messages.length, messages: messages.slice(-last) }\n}\n\n// ---------------------------------------------------------------------------\n// Runs: one headless turn per run, executed by a detached runner process so it\n// survives the MCP server restarting. Each run lives in <batonHome>/runs/<id>/.\n\nfunction runsDir() {\n  return path.join(config.batonHome, 'runs')\n}\n\n// Run records hold full prompts and replies: keep them private to this user.\nfunction ensurePrivateDir(dir) {\n  fs.mkdirSync(dir, { recursive: true, mode: 0o700 })\n  fs.chmodSync(dir, 0o700)\n}\n\nfunction runDir(runId) {\n  if (!/^run-[\\w-]+$/.test(runId)) throw new Error(`Invalid run id: ${runId}`)\n  return path.join(runsDir(), runId)\n}\n\nfunction readJson(file) {\n  try { return JSON.parse(fs.readFileSync(file, 'utf8')) } catch { return null }\n}\n\nfunction writeJson(file, value) {\n  const tmp = `${file}.${process.pid}.tmp`\n  fs.writeFileSync(tmp, JSON.stringify(value, null, 2), { mode: 0o600 })\n  fs.renameSync(tmp, file)\n}\n\nconst cancelFlag = (dir) => path.join(dir, 'cancelled')\n\nfunction writeExit(dir, exit) {\n  writeJson(path.join(dir, 'exit.json'), { ended_at: new Date().toISOString(), ...exit })\n}\n\nfunction alive(pid) {\n  if (!pid) return false\n  try { process.kill(pid, 0); return true } catch (e) { return e.code === 'EPERM' }\n}\n\nfunction activeRunFor(sessionId) {\n  if (!sessionId || !fs.existsSync(runsDir())) return null\n  for (const id of fs.readdirSync(runsDir())) {\n    const st = runStatus(id, { tail: 0 })\n    if (st.session_id === sessionId && st.state === 'running') return st\n  }\n  return null\n}\n\nexport function startRun({ message, session_id, cwd }) {\n  if (!message || !message.trim()) throw new Error('message is required')\n  let workdir\n  if (session_id) {\n    const busy = activeRunFor(session_id)\n    if (busy) throw new Error(`Session ${session_id} is already running ${busy.run_id}; wait for it or cancel it first.`)\n    const info = summarize(readSessionRecords(sessionFile(findSessionDir(session_id).dir), 64 * 1024), session_id)\n    workdir = info.cwd\n  } else {\n    if (!cwd) throw new Error('A new session needs cwd (the workspace folder). Pass session_id to continue an existing one.')\n    workdir = normalizePath(cwd)\n  }\n  if (!workdir || !fs.existsSync(workdir)) throw new Error(`Workspace folder does not exist: ${workdir}`)\n\n  const runId = `run-${new Date().toISOString().replace(/[-:T]/g, '').slice(0, 14)}-${crypto.randomBytes(3).toString('hex')}`\n  const dir = runDir(runId)\n  ensurePrivateDir(config.batonHome)\n  ensurePrivateDir(runsDir())\n  ensurePrivateDir(dir)\n  fs.writeFileSync(path.join(dir, 'message.txt'), message, { mode: 0o600 })\n  writeJson(path.join(dir, 'meta.json'), {\n    run_id: runId, session_id: session_id || null, cwd: workdir, started_at: new Date().toISOString(),\n    message_preview: message.slice(0, 200),\n  })\n\n  const runner = spawn(process.execPath, [path.join(HERE, 'cli.mjs'), '_run', runId], {\n    detached: true, stdio: 'ignore', cwd: workdir, env: process.env, windowsHide: true,\n  })\n  runner.unref()\n  return runId\n}\n\n// Executed inside the detached runner process.\nexport async function executeRun(runId) {\n  const dir = runDir(runId)\n  const meta = readJson(path.join(dir, 'meta.json'))\n  const args = ['headless', ...patchArgs(), '--json']\n  if (meta.session_id) args.push('--session-id', meta.session_id)\n  args.push('-')\n\n  // A cancel that arrived before the child started: never start it.\n  if (fs.existsSync(cancelFlag(dir))) return writeExit(dir, { exit_code: null, signal: null, state: 'cancelled' })\n\n  const events = fs.createWriteStream(path.join(dir, 'events.ndjson'), { mode: 0o600 })\n  const stderr = fs.openSync(path.join(dir, 'stderr.log'), 'w', 0o600)\n  // No dsh found at all is a failed run with a reason, not a runner that dies silently.\n  let launch\n  try { launch = dshCommand(args) } catch (error) {\n    events.end()\n    fs.writeSync(stderr, `dsh: ${error.message}\\n`)\n    return writeExit(dir, { exit_code: null, signal: null, state: 'failed' })\n  }\n  const child = spawn(launch.file, launch.args, { cwd: meta.cwd, stdio: ['pipe', 'pipe', stderr], env: process.env, windowsHide: true, ...launch.options })\n  // A dsh that cannot start (missing, not executable) is a failed run, not a crashed runner.\n  const started = new Promise((resolve) => child.once('error', (error) => resolve(error)))\n  child.stdin.on('error', () => {})\n  writeJson(path.join(dir, 'pid.json'), { runner: process.pid, dsh: child.pid })\n  // A cancel that arrived while the child was starting (before pid.json existed).\n  if (fs.existsSync(cancelFlag(dir))) { try { IS_WIN ? stopProcess(child.pid) : child.kill('SIGTERM') } catch { /* not started */ } }\n  fs.createReadStream(path.join(dir, 'message.txt')).pipe(child.stdin)\n\n  // Keep only JSON lines; the CLI also prints plain log lines on stdout.\n  let pending = ''\n  child.stdout.on('data', (chunk) => {\n    pending += chunk\n    const lines = pending.split('\\n')\n    pending = lines.pop()\n    for (const raw of lines) {\n      const line = raw.endsWith('\\r') ? raw.slice(0, -1) : raw // CRLF output on Windows\n      if (line.startsWith('{')) events.write(line + '\\n')\n    }\n  })\n\n  const spawnError = await Promise.race([started, new Promise((resolve) => child.once('spawn', () => resolve(null)))])\n  if (spawnError) {\n    events.end()\n    fs.writeSync(stderr, `dsh: could not start ${launch.file}: ${spawnError.message}\\n`)\n    return writeExit(dir, { exit_code: null, signal: null, state: 'failed' })\n  }\n  const [code, signal] = await new Promise((resolve) => child.on('close', (c, s) => resolve([c, s])))\n  if (pending.startsWith('{')) events.write(pending + '\\n')\n  await new Promise((resolve) => events.end(resolve))\n  const cancelled = fs.existsSync(cancelFlag(dir))\n  writeExit(dir, { exit_code: code, signal, state: cancelled ? 'cancelled' : code === 0 ? 'completed' : 'failed' })\n}\n\nexport function runStatus(runId, { tail = 20 } = {}) {\n  const dir = runDir(runId)\n  const meta = readJson(path.join(dir, 'meta.json'))\n  if (!meta) throw new Error(`Unknown run: ${runId}`)\n  const exit = readJson(path.join(dir, 'exit.json'))\n  const pids = readJson(path.join(dir, 'pid.json'))\n\n  let sessionId = meta.session_id, finalText = null, turnEnd = null, usage = { inputTokens: 0, outputTokens: 0 }\n  const timeline = []\n  let raw = ''\n  try { raw = fs.readFileSync(path.join(dir, 'events.ndjson'), 'utf8') } catch { /* not started */ }\n  for (const line of raw.split('\\n')) {\n    if (!line) continue\n    let e\n    try { e = JSON.parse(line) } catch { continue }\n    if (e.type === 'session') sessionId = e.sessionId\n    else if (e.type === 'final') finalText = e.text\n    else if (e.type === 'text' && e.text) timeline.push({ type: 'text', text: e.text })\n    else if (e.type === 'status' && e.phase === 'turn_end') turnEnd = e.reason\n    else if (e.type === 'status' && e.phase === 'step_end' && e.usage) {\n      usage.inputTokens += e.usage.inputTokens || 0\n      usage.outputTokens += e.usage.outputTokens || 0\n    } else if (e.type !== 'status' && e.type !== 'thinking') timeline.push(e)\n  }\n\n  let state = exit?.state\n  // No pid file yet means the runner is still starting; give it 30 s before calling it failed.\n  if (!state) state = pids ? (alive(pids.runner) ? 'running' : 'failed') : (Date.now() - Date.parse(meta.started_at) < 30_000 ? 'running' : 'failed')\n  if (state === 'failed' && !exit && fs.existsSync(cancelFlag(dir))) state = 'cancelled'\n  let error = timeline.filter((e) => e.type === 'error').map((e) => e.message).join('\\n') || null\n  if (state === 'failed' && !error) {\n    try { error = fs.readFileSync(path.join(dir, 'stderr.log'), 'utf8').split('\\n').filter((l) => l.startsWith('dsh: ') || /error/i.test(l)).slice(-5).join('\\n') || null } catch { /* none */ }\n  }\n  return {\n    run_id: runId, state, session_id: sessionId, cwd: meta.cwd, started_at: meta.started_at, ended_at: exit?.ended_at ?? null,\n    message_preview: meta.message_preview, turn_end: turnEnd, final_text: finalText, usage, error,\n    ...(tail ? { recent_events: timeline.slice(-tail) } : {}),\n  }\n}\n\nexport async function waitRun(runId, { timeout_s = 300, poll_ms = 1000 } = {}) {\n  const deadline = Date.now() + timeout_s * 1000\n  for (;;) {\n    const st = runStatus(runId)\n    if (st.state !== 'running') return st\n    if (Date.now() >= deadline) return { ...st, timed_out: true }\n    await new Promise((r) => setTimeout(r, poll_ms))\n  }\n}\n\n// Resolves once the run has reported its session id (new sessions get one at start).\nexport async function waitForSessionId(runId, timeoutMs = 8000) {\n  const deadline = Date.now() + timeoutMs\n  while (Date.now() < deadline) {\n    const st = runStatus(runId, { tail: 0 })\n    if (st.session_id || st.state !== 'running') return st\n    await new Promise((r) => setTimeout(r, 250))\n  }\n  return runStatus(runId, { tail: 0 })\n}\n\n// Stop only the dsh child; the runner stays alive to record the cancelled state.\n// Without a pid yet, the runner sees the flag and does not start (or stops) the child.\nexport function cancelRun(runId) {\n  const dir = runDir(runId)\n  const st = runStatus(runId, { tail: 0 })\n  if (st.state !== 'running') return st\n  fs.writeFileSync(cancelFlag(dir), '', { mode: 0o600 })\n  const pids = readJson(path.join(dir, 'pid.json'))\n  if (pids?.dsh) { try { stopProcess(pids.dsh) } catch { /* already gone */ } }\n  if (pids && !alive(pids.runner)) writeExit(dir, { exit_code: null, signal: null, state: 'cancelled' })\n  return { ...st, state: 'cancelling' }\n}\n\nexport function listRuns({ limit = 10, session_id } = {}) {\n  if (!fs.existsSync(runsDir())) return []\n  const ids = fs.readdirSync(runsDir()).filter((d) => d.startsWith('run-')).sort().reverse()\n  return (session_id ? ids : ids.slice(0, limit))\n    .map((id) => { try { return runStatus(id, { tail: 0 }) } catch { return null } })\n    .filter((r) => r && (!session_id || r.session_id === session_id)).slice(0, limit)\n}\n\n// ---------------------------------------------------------------------------\n// Backend routing. DSH_BATON_BACKEND = auto (default) | host | headless.\n// auto uses the host plugin when its socket answers, else falls back to headless.\n\nasync function useHost() {\n  const mode = setting('BACKEND') || 'auto'\n  if (mode === 'headless') return false\n  const up = await hostAvailable()\n  if (!up && mode === 'host') throw new Error(`dsh-baton-host is not reachable at ${hostSocket()}. Is DeepSeek Harness running with the dsh-baton-host plugin enabled?`)\n  return up\n}\n\n// Said with a finished run's reply: review from the evidence dsh-baton produced, read code only\n// where it points, and send every fix back in one message. In the message's language: Chinese\n// when it has CJK characters, else English.\nexport function reviewRequest(message) {\n  return /[\\u3040-\\u30ff\\u3400-\\u9fff\\uac00-\\ud7af\\uf900-\\ufaff]/.test(message)\n    ? '\\n\\n---\\n完成后，启动一个只读子代理，对照上面的每一项需求检查，然后在最终回复末尾附上它的表格：需求 | 是否满足（是 / 否 / 不确定）| 证据（文件:行 或测试名）。标为\"否\"的先修好再回复。'\n    : '\\n\\n---\\nWhen the work is done, start a read-only sub-agent to check it against every requirement above, then end your final reply with its table: requirement | met (yes / no / unclear) | evidence (file:line or test name). Fix anything marked no before replying.'\n}\n\nexport const ENDED_HINT = 'evidence is produced by dsh-baton (files changed, checks it ran), not by the Harness reply: trust it over final_text. If a check failed, a requirement has no check, or a file the task needs is missing from evidence.changes, send all fixes back in one message to the same session, quoting the failing output; do not reproduce failures or write test scripts yourself. If every check passed and final_text ends with a review table whose rows are all met, accept it without reading code; read code only for rows marked no or unclear.'\n// Sent without checks there is no check output to come: a follow-up only to get one costs a\n// round and tells nothing the review table does not.\nconst NO_CHECKS_HINT = 'evidence is produced by dsh-baton (files changed), not by the Harness reply. This message was sent without checks, so there is no check output to wait for: do not send a follow-up only to get one. If a file the task needs is missing from evidence.changes or final_text reports a failure, send all fixes back in one message to the same session; do not reproduce failures or write test scripts yourself. If final_text ends with a review table whose rows are all met, accept it without reading code; read code only for rows marked no or unclear.'\n// A check that failed because a command or module was not found ran in another environment\n// than Harness used (another python, PATH), which says nothing about the code.\nconst MISSING_TOOL = /command not found|not recognized as (?:an internal|the name)|No module named|ModuleNotFoundError|Cannot find module|: not found\\b/i\nconst ENV_HINT = ' A failed check whose output says a command or module was not found most likely ran in another environment than Harness used (another interpreter or PATH), not against broken code: ask Harness to run that check the way it ran its own tests (its interpreter or venv) instead of asking for code fixes.'\n// Runs that worked in the same folder at the same time put their changes in each other's\n// evidence: a file this run did not make may be another's, so it is not to be removed.\nconst SHARED_HINT = (runs) => ` Other runs (${runs.join(', ')}) worked in this folder at the same time, so evidence.changes may include their files: never delete or revert a file because this run was not asked for it.`\n// A folder too big to look at whole: a file missing from evidence.changes proves nothing.\nconst TRUNCATED_HINT = ' The folder has more files than dsh-baton looks at, so evidence.changes may miss some: do not take a file missing from it as not written.'\nexport function endedHint(st) {\n  const checks = st?.evidence?.checks\n  const shared = (st?.evidence?.same_folder_runs?.length ? SHARED_HINT(st.evidence.same_folder_runs) : '') + (st?.evidence?.changes?.truncated ? TRUNCATED_HINT : '')\n  const hint = !checks?.length ? NO_CHECKS_HINT + shared : ENDED_HINT + (checks.some((c) => !c.passed && MISSING_TOOL.test(c.output_tail ?? '')) ? ENV_HINT : '') + shared\n  return st?.goal ? `${goalHint(st.goal, st.session_id)} ${hint}` : hint\n}\n\n// A Harness goal starts the session's next round by itself as soon as a turn ends, so a run\n// that completed there is one stage of the work, not its end.\nconst FOLLOW_HOW = (sid) => `To follow it to its end, send nothing: call dsh_wait with session_id ${sid} (until \"goal\", the default, reports once when the goal stops; until \"turn\", when the user asked for progress reports, at most every 10 minutes, at the end of a round, with every round since the last report).`\nexport function goalHint(goal, sid) {\n  if (goal.phase === 'active' && goal.activation !== 'disarmed') {\n    return `This session has an active Harness goal (${goal.rounds_started} goal round(s) started${goal.max_rounds ? `, at most ${goal.max_rounds}` : ''}): Harness goes on with the next round by itself after this reply, so the work is not finished. Report this stage to the user as one stage. ${FOLLOW_HOW(sid)}`\n  }\n  if (goal.phase === 'active') return 'This session has an active Harness goal, but Harness will not go on with it by itself (for example after a Harness restart): tell the user to press Continue in Harness if they want it to go on.'\n  return `The session's Harness goal is ${goal.phase}${goal.blocked_reason ? ` (${goal.blocked_reason.code}: ${goal.blocked_reason.message})` : ''}: it does not go on until the user deals with it in Harness.`\n}\n\n// A run in a session whose Harness goal goes on: its wait goes on with the goal.\n// Also one that stopped after the run began: the rounds after the run's are its work too.\nexport const goalGoesOn = (st) => st?.state === 'completed' && !!st.session_id && !!st.goal && ((st.goal.phase === 'active' && st.goal.activation !== 'disarmed') || !!st.goal.ended_since_run)\n// The run's wait followed on through its goal (f, from followResult): the follow's result, with\n// any answer chosen for the user during the run, and, once the goal stopped, the run's checks\n// run again then (budget_ms; without the time, the ones from the end of the run's own round).\nexport function throughGoal(run, f, { budget_ms = 180_000 } = {}) {\n  const chose = run.decided_for_user ? 'You chose an answer for the user during this run (decided_for_user): start your reply by telling the user what you chose and why. ' : ''\n  const final = f.state === 'goal_ended' && run.evidence?.checks?.length\n  const again = final && budget_ms >= 5000 ? evidence.recheck(config.batonHome, run.run_id, budget_ms) : null\n  return {\n    ...f, run_id: run.run_id,\n    ...(final ? (again ? { checks: again, all_checks_passed: again.every((c) => c.passed) } : { checks: run.evidence.checks, checks_from: 'the end of the run\\'s own round (no time left to run them again)' }) : {}),\n    ...(run.decided_for_user ? { decided_for_user: run.decided_for_user } : {}),\n    // Going on through the run keeps the run's checks for the goal's end.\n    ...(f.hint ? { hint: chose + f.hint.replaceAll(AGAIN, AGAIN.replace('session_id', 'run_id')) } : {}),\n  }\n}\n\n// What a follow wait (dsh_wait with session_id) returns, with what to do next.\nconst AGAIN = 'call dsh_wait again with the same session_id, until and this cursor'\nconst QUIET = 'While waiting, write no progress sentences.'\nexport function followResult(st) {\n  const report = `Report to the user briefly, in their language: what the rounds did (the latest round's final_text, each earlier round's summary and tools), the files changed (changed_files) and how far the goal is (goal.rounds_started of goal.max_rounds).${st.rounds?.length > 1 ? ` For one round in full, read it with dsh_read_session (session_id ${st.session_id}) only if the user asks.` : ''}`\n  switch (st.state) {\n    case 'report': return { ...st, hint: `${report} Then ${AGAIN}. ${QUIET}` }\n    case 'following': return { ...st, hint: `No report is due yet: ${AGAIN}, with no progress note in between. ${QUIET}` }\n    case 'goal_ended': return { ...st, hint: `The goal stopped (${st.ended_because}${st.goal?.blocked_reason ? `: ${st.goal.blocked_reason.message}` : ''}), so following is over. ${report}${st.ended_because === 'blocked' || st.ended_because === 'paused' ? ' It needs the user before it goes on: say so.' : ''}` }\n    case 'needs_input': return st.question\n      ? asking(st, askHint(st.question.count, `dsh_answer and session_id ${st.session_id} (no run_id)`, AGAIN))\n      : { ...st, hint: `Harness waits for something only a person can do in its window (an approval, for example). Tell the user, then ${AGAIN}.` }\n    case 'needs_resume': return { ...st, hint: 'The goal is still active, but Harness will not go on with it by itself (for example after a Harness restart). Tell the user to press Continue in Harness, and stop following until they have.' }\n    case 'goal_stalled': return { ...st, hint: 'The goal is active, yet no new round has started for 5 minutes: Harness may have stopped going on with it (for example after a restart). Tell the user; they can press Continue in Harness. Stop following until they have.' }\n    case 'no_goal': return { ...st, hint: 'This session has no Harness goal, so there is nothing to follow. To get a reply from it, send a message with dsh_send and wait for that run.' }\n    default: return st\n  }\n}\n\n// A run that stopped because the DeepSeek balance ran out: sending again fails the same way.\nexport const QUOTA_HINT = 'The run stopped because the DeepSeek account has no balance left. Do not send again or retry: every send fails the same way until the balance is topped up. Tell the user, in their language, to top up (Harness → Settings → Account, or platform.deepseek.com), then send to the same session to continue where it stopped.'\nconst outOfBalance = (st) => st.state === 'failed' && (['ACCOUNT_QUOTA', 'QUOTA'].includes(st.turn_end?.error?.code) || st.turn_end?.error?.status === 402 || /insufficient balance/i.test(st.error ?? ''))\n\n// What to do when a run stops to ask a person (dsh_wait, wait_command and the instructions say it).\n// The options are the asking model's guesses, not the limit of the answer: every question also\n// takes free text (on a single-choice question it replaces the option, Harness's own rule).\n// The user wants the client to decide as the owner of the task, not pick the least bad option.\nexport const OWN_WORDS = 'On a single choice, text replaces the option.'\nexport const ASKED = `If the user told you to decide such questions yourself, decide as the task's owner: an option only if it fits as is, else your own words. ${OWN_WORDS} Call dsh_answer with a one-sentence reason, then tell the user what you answered and why. Otherwise relay the questions, starting with your advice on its own line: \"My recommendation: <an option, or your own answer>, because <reason>\", from your own judgment, even outside the options (harness_suggested is only the asker's pick, never a reason). List the options (the user may also answer in words) and submit their decision with dsh_answer. Never answer on the user's behalf without that permission.`\nexport const DECIDED_HINT = 'Required in your reply: you answered for the user during this run, so start your reply by telling the user, in their language, what you answered (an option or your own words) and why (decided_for_user: answers and reason), then give the result. Passing on only final_text is not enough.'\n// What to do when a run asks the user, in one short hint that goes first in the result.\n// Codex relays through its own question tool (request_user_input: a title and plain option\n// strings); the message before that call is folded away in the Codex app, so a recommendation\n// written only there is lost (Mac, 2026-11-08), and longer hints did not change that. The\n// result therefore carries question_tool, the call laid out with the recommendation as its first\n// option, as relay is the message laid out with it as its first line: clients copy a layout\n// more reliably than they follow rules.\nexport const askHint = (n, answerWith, then) => `Harness asks the user ${n} question(s). If the user let you decide such questions, answer as the task's owner: an option only if it fits as is, else your own words (text; ${OWN_WORDS.toLowerCase().replace(/\\.$/, '')}). An option that needs a note, a fix or an explanation to work for this task does not fit: write the answer it should have been instead. Answer with ${answerWith} and a one-sentence reason, then tell the user what you answered and why. Otherwise ask the user, your own recommendation first: fill the first line of relay (in a message) or the first option of question_tool (in a question tool such as request_user_input) with the answer that best fits this task, checked against its file names and requirements (an option, or your own answer when none fits), and why. Never \"your choice\", nor the asker's pick (harness_suggested) unchecked. If they pick your recommendation, submit the answer alone, without \"Recommended\" or the reason. Submit their answer with ${answerWith}, then ${then}.`\nconst NEEDS_INPUT_HINT = (st) => st.question\n  ? askHint(st.question.count, 'dsh_answer', 'wait for the run again')\n  : 'The run waits for something only a person can do in the Harness UI (an approval, for example). Tell the user, then wait for the run again.'\n// The hint first, then the question laid out two ways, then the rest of the status.\nexport function asking(st, hint) {\n  const { hint: _old, relay: _r, question_tool: _q, ...rest } = st\n  return { hint, ...(st.question ? { relay: relayText(st.question), question_tool: questionTool(st.question) } : {}), ...rest }\n}\n\n// A run the user stopped in the Harness UI: its turn ended aborted, by the user. With the usual\n// hint, Codex took that for a failure and sent the task again each time the user stopped it\n// (Windows, 2026-11-08). The UI stop leaves background jobs of the session running; dsh_cancel\n// stops them too.\nexport const stoppedByUser = (st) => st?.state === 'failed' && st.turn_end?.kind === 'aborted' && st.turn_end?.reason?.kind === 'user'\nexport const USER_STOPPED_HINT = 'The user stopped this run in Harness (stopped_by_user). It is not a failure to repair: do not send it again, continue it or send fixes. Tell the user it was stopped and what evidence shows it got done, then ask what to do next. Background jobs it started may still be running in that session; stop them with dsh_cancel and its session_id only if the user asks.'\n// Ended by something other than the work: Harness restarting under the run, or a cancel (dsh_cancel,\n// or in Harness: the user stopping the session drops its queued messages, or removing one). Sending\n// again on one's own would override the user here too.\nexport const INTERRUPTED_HINT = 'Harness restarted or quit while this run was going, and its turn was stopped (interrupted). It is not a failure in the work: do not send it again or continue it on your own. Tell the user Harness was restarted and what evidence shows the run got done, then ask whether to run it again or continue in the same session.'\nexport const CANCELLED_HINT = 'This run was cancelled before it finished: with dsh_cancel, or in Harness, where the user stopped the session or removed the queued message. If you did not cancel it yourself, the user did: do not send it again. Tell the user it was cancelled and ask what to do next.'\n// The hint for a run that did not end by its own work, or null for one that did.\n// A run that answered a question for the user before it stopped keeps the sentence telling the\n// client to say so.\nexport function stopHint(st) {\n  const told = (hint) => (st?.decided_for_user ? `${DECIDED_STOPPED} ${hint}` : hint)\n  if (stoppedByUser(st)) return { stopped_by_user: true, hint: told(USER_STOPPED_HINT) }\n  if (st?.state === 'interrupted') return { hint: told(INTERRUPTED_HINT) }\n  if (st?.state === 'cancelled') return { hint: told(CANCELLED_HINT) }\n  return null\n}\nconst DECIDED_STOPPED = 'You answered a question for the user during this run: tell the user, in their language, what you answered and why (decided_for_user: answers and reason).'\n\n// The result of a run that ended, kept short: the client already knows what it sent, and a\n// completed run's event log is only the work behind final_text (dsh_status still has it).\n// A run that did not complete keeps its last events, to show where it stopped.\nfunction ended({ recent_events, message_preview, backend, ...st }) {\n  const out = { ...st, ...(st.state !== 'completed' && recent_events?.length ? { recent_events: recent_events.slice(-5) } : {}) }\n  if (outOfBalance(st)) return { ...out, hint: QUOTA_HINT }\n  const stop = stopHint(st)\n  if (stop) return { ...out, ...stop }\n  // decided_for_user first, so a client that skims to final_text still meets it.\n  return st.decided_for_user\n    ? { hint: `${DECIDED_HINT} ${endedHint(st)}`, decided_for_user: st.decided_for_user, ...out }\n    : { ...out, hint: endedHint(st) }\n}\n\n\n// What dsh_wait returns for a run that ended or stopped to ask (the Codex Stop hook returns the same).\nexport const waitResult = (st) => (st.needs_input ? asking(st, NEEDS_INPUT_HINT(st)) : ended(st))\n\n// The asking model marks its favourite option in the label (\"(Recommended)\", \"（推荐）\").\n// Clients relaying the question tended to repeat that mark as their own advice, so the\n// label is cleaned and the mark moves to harness_suggested: what the asker suggests, kept\n// apart from the recommendation the client has to form itself. Harness still matches a\n// cleaned label when it is chosen by label.\nconst MARK = /\\s*(?:\\((?:recommended|推荐)\\)|（(?:recommended|推荐)）)\\s*/gi\nconst cleanLabel = (label) => String(label).replace(MARK, ' ').trim()\nexport function shapeQuestion(question) {\n  if (!Array.isArray(question?.questions)) return question\n  return {\n    ...question,\n    questions: question.questions.map((q) => {\n      let suggested = null\n      const options = (q.options ?? []).map(({ recommended, ...o }) => {\n        const label = cleanLabel(o.label)\n        if (!suggested && (recommended || label !== o.label)) suggested = { number: o.number, label }\n        return { ...o, label }\n      })\n      return { ...q, options, ...(suggested ? { harness_suggested: suggested } : {}) }\n    }),\n  }\n}\n// The question laid out for the user, ready to show: the first line is left for the\n// client's own recommendation, the asker's pick comes last and only as information.\n// Weaker models fill in a template more reliably than they follow a paragraph of rules.\nexport function relayText(question) {\n  if (!Array.isArray(question?.questions)) return undefined\n  const blocks = question.questions.map((q, i) => {\n    const head = `${question.questions.length > 1 ? `${i + 1}. ` : ''}${q.question}${q.multi_select ? ' (several can be chosen)' : ''}`\n    const options = (q.options ?? []).map((o) => `  ${o.number}. ${o.label}${o.description ? ` - ${o.description}` : ''}`)\n    const asker = q.harness_suggested ? [`  (The model in Harness that asked would pick: ${q.harness_suggested.label})`] : []\n    return [head, ...options, ...asker].join('\\n')\n  })\n  return [RECOMMEND_LINE, '', ...blocks, '', 'You can also answer in your own words.'].join('\\n')\n}\nconst RECOMMEND_LINE = 'My recommendation: <an option, or your own answer>, because <your own reason>'\n// The same questions as a question tool takes them (a title, plain option strings), the first\n// option left for the client's recommendation; the user can still type their own answer there.\nexport function questionTool(question) {\n  if (!Array.isArray(question?.questions)) return undefined\n  return question.questions.map((q) => ({\n    title: `${q.question}${q.multi_select ? ' (several can be chosen)' : ''}`,\n    options: ['Recommended: <an option, or your own answer>, because <your own reason>', ...(q.options ?? []).map((o) => o.label)],\n  }))\n}\n\n// When the client chose for the user (dsh_answer with reason), the choice and reason are\n// kept until the run ends: the final wait result carries them, so the client tells the\n// user then, instead of only passing on the reply. A file, because the client may wait\n// from another process (wait_command).\nconst reasonsFile = () => path.join(config.batonHome, 'answer-reasons.json')\nconst readReasons = () => { try { return JSON.parse(fs.readFileSync(reasonsFile(), 'utf8')) } catch { return {} } }\n// A client deciding for the user picked the least bad option and patched it with a note\n// (\".doc, but keep it plain text\"; \"XV:00, with a line saying it means 3 pm\"), however the hint\n// put it (Codex, Mac, 2026-11-09). So an option chosen for the user is not sent at once: the\n// first call asks for a second look, and the same answers sent again go through. Own words\n// (text) go through at once, as do answers the user gave (no reason).\nexport const OPTION_CHECK_HINT = 'Not sent yet, because you chose an option for the user. First, without looking at the options, write down the answer this user would want for this task, as if Harness had asked with no options at all. Send the option (dsh_answer again with the same answers) only if it says the same as that answer. If it does not, answer with text: your answer. An option you can argue for, or make work with a note or an explanation, is not the answer this user would want.'\nconst checked = new Map()\nexport function optionCheck(a, reason) {\n  if (!(typeof reason === 'string' && reason.trim())) return null\n  const picks = (a.answers ?? []).filter((x) => x.choose?.length && !(typeof x.text === 'string' && x.text.trim()))\n  if (!picks.length) return null\n  const key = JSON.stringify([a.run_id ?? a.session_id, picks.map((x) => [x.id ?? null, x.choose.map(String)])])\n  for (const [k, at] of checked) if (Date.now() - at > 30 * 60_000) checked.delete(k)\n  if (checked.delete(key)) return null\n  checked.set(key, Date.now())\n  return { submitted: false, check: picks.map((x) => ({ ...(x.id ? { id: x.id } : {}), choose: x.choose })), hint: OPTION_CHECK_HINT }\n}\nfunction rememberReason(runId, answers, reason) {\n  try {\n    const all = readReasons()\n    all[runId] = { answers: (answers ?? []).map((a) => ({ id: a.id, selected: (a.selected ?? []).map(cleanLabel), ...(a.custom ? { text: a.custom } : {}) })), reason, at: Date.now() }\n    const kept = Object.entries(all).sort((x, y) => y[1].at - x[1].at).slice(0, 50)\n    ensurePrivateDir(config.batonHome)\n    fs.writeFileSync(reasonsFile(), JSON.stringify(Object.fromEntries(kept)), { mode: 0o600 })\n  } catch { /* the reason is a courtesy; answering never fails over it */ }\n}\nconst ENDED = new Set(['completed', 'failed', 'cancelled', 'interrupted'])\nconst shaped = (st) => {\n  if (!st || typeof st !== 'object') return st\n  let out = st.question ? { ...st, question: shapeQuestion(st.question) } : st\n  const decided = ENDED.has(st.state) && st.run_id ? readReasons()[st.run_id] : null\n  if (decided) out = { ...out, decided_for_user: { answers: decided.answers, reason: decided.reason } }\n  return Array.isArray(st.answers) ? { ...out, answers: st.answers.map((a) => (Array.isArray(a?.selected) ? { ...a, selected: a.selected.map(cleanLabel) } : a)) } : out\n}\n\n// The folder a run works in: given with dsh_send, or that of its workspace or session.\nasync function runFolder(a, st) {\n  if (a.cwd) return path.resolve(a.cwd.replace(/^~(?=$|[\\\\/])/, os.homedir()))\n  if (st?.cwd) return st.cwd\n  try {\n    if (a.workspace_id) return (await api.workspaces()).find((w) => w.id === a.workspace_id)?.path\n    const sid = a.session_id ?? st?.session_id\n    if (sid) return (await api.list_sessions({ query: sid, limit: 5 })).find((x) => x.session_id === sid)?.cwd\n  } catch { /* no folder, no evidence */ }\n  return undefined\n}\nconst withEvidence = (st) => {\n  if (!st || !ENDED.has(st.state) || !st.run_id) return st\n  const ev = evidence.collect(config.batonHome, st.run_id)\n  return ev ? { ...st, evidence: ev } : st\n}\n\n// An older plugin answers a method it does not have with \"Unknown method\": say to update it.\nconst tooOld = (method, what) => (error) => {\n  if (!new RegExp(`Unknown method: ${method}|Unknown run: undefined`).test(error?.message)) throw error\n  throw new Error(`The Harness plugin dsh-baton-host ${hostVersion ?? ''} is too old to ${what}; this MCP server is ${VERSION}. Update the plugin in Harness: Plugins → dsh-baton-host → Uninstall, then Add plugin → dsh-baton-host@${VERSION}.`.replace('  ', ' '))\n}\n\nconst tag = (backend, value) => (Array.isArray(value) ? value.map((v) => ({ ...v, backend })) : { ...value, backend })\n\n// Follow a goal for up to total_s, one host call per chunk_s, from the same cursor each time.\n// A host that went away (Harness restarting or updating) is waited for, HOST_BACK_MS at most:\n// the follow then goes on and finds the goal as Harness left it (after a restart, disarmed).\nconst HOST_BACK_MS = 180_000\nconst hostGone = (e) => !!e?.hostDown || /closed the connection|needs the dsh-baton-host plugin running|did not answer/.test(e?.message ?? '')\nexport async function followThrough(params, { total_s, chunk_s = 300, onChunk, signal } = {}) {\n  const started = Date.now()\n  const deadline = started + total_s * 1000\n  let cursor = params.cursor, since_ms = params.since_ms, lostSince = null\n  for (;;) {\n    if (signal?.aborted) return { session_id: params.session_id, cancelled: true }\n    const left = Math.ceil((deadline - Date.now()) / 1000)\n    let st\n    try {\n      st = await api.follow({ ...params, cursor, since_ms: cursor ? undefined : since_ms, timeout_s: Math.max(1, Math.min(chunk_s, left)) })\n      lostSince = null\n    } catch (e) {\n      if (!hostGone(e)) throw e\n      lostSince ??= Date.now()\n      // No cursor yet: go on from when this follow began, not from after the restart.\n      since_ms ??= started\n      if (Date.now() - lostSince > HOST_BACK_MS || Date.now() >= deadline) throw e\n      await new Promise((r) => setTimeout(r, 5000))\n      continue\n    }\n    if (!st.timed_out || Date.now() >= deadline) return st\n    cursor = st.cursor\n    onChunk?.(st)\n  }\n}\n\n// How often a wait looks for Harness again while it is not running.\nconst HOST_RETRY_MS = Number(process.env.DSH_BATON_HOST_RETRY_MS) || 2000\n// again: how to wait once Harness is back (dsh_wait for one run or several, or the CLI command).\nexport const harnessDownHint = (again = 'call dsh_wait again with the same run_id') => `DeepSeek Harness is not running (closed, or restarting), so the run cannot be followed right now; Harness ends a running turn when it quits. Do not send the task again. Tell the user Harness is closed and to open it; then ${again}: it reports how the run ended (interrupted, if Harness quit while it ran).`\nexport const HARNESS_DOWN_HINT = harnessDownHint()\n\nexport const api = {\n  async workspaces() {\n    if (!(await useHost())) throw new Error('Listing workspaces needs the dsh-baton-host plugin running inside DeepSeek Harness.')\n    return hostCall('workspaces')\n  },\n  async models() {\n    if (!(await useHost())) throw new Error('Listing models needs the dsh-baton-host plugin running inside DeepSeek Harness.')\n    try {\n      return await hostCall('models')\n    } catch (error) {\n      if (!/Unknown method: models/.test(error?.message)) throw error\n      throw new Error(`The Harness plugin dsh-baton-host ${hostVersion ?? ''} is too old to list models; this MCP server is ${VERSION}. Update the plugin: Plugins → dsh-baton-host → Uninstall, then Add plugin → dsh-baton-host@${VERSION}.`.replace('  ', ' '))\n    }\n  },\n  async create_workspace(a) {\n    if (!(await useHost())) throw new Error('Creating workspaces needs the dsh-baton-host plugin running inside DeepSeek Harness.')\n    return hostCall('create_workspace', a)\n  },\n  async list_sessions(a = {}) {\n    return (await useHost()) ? tag('host', await hostCall('list_sessions', a)) : tag('headless', listSessions(a))\n  },\n  async read_session(a) {\n    return (await useHost()) ? tag('host', await hostCall('read_session', a)) : tag('headless', readSession(a))\n  },\n  // checks stay here: dsh-baton runs them itself when the run ends (see evidence.mjs).\n  // A hand-over (a message with checks) also asks Harness to have a read-only sub-agent\n  // review the work against the spec and end with a table, so the client can decide from\n  // that table and the evidence instead of reading the code itself.\n  async send({ checks, ...a }) {\n    if (Array.isArray(checks) && checks.length && typeof a.message === 'string') a = { ...a, message: `${a.message}${reviewRequest(a.message)}` }\n    const host = await useHost()\n    if (a.model != null || a.reasoning_effort != null) {\n      if (!host) throw new Error('Choosing a model needs the dsh-baton-host plugin running inside DeepSeek Harness. Nothing was sent; send again without model and reasoning_effort to use the Harness default.')\n      // An older plugin would drop model silently and run on the default: ask it first.\n      await hostCall('models').catch((error) => {\n        if (!/Unknown method: models/.test(error?.message)) throw error\n        throw new Error(`The Harness plugin dsh-baton-host ${hostVersion ?? ''} is too old to choose a model; this MCP server is ${VERSION}. Nothing was sent. Update the plugin: Plugins → dsh-baton-host → Uninstall, then Add plugin → dsh-baton-host@${VERSION}, or send without model.`.replace('  ', ' '))\n      })\n    }\n    // A client whose tool list predates team (a conversation open since before an update) sends\n    // it as the string \"true\" or \"false\": take that as the boolean it means.\n    if (typeof a.team === 'string' && /^(true|false)$/i.test(a.team.trim())) a = { ...a, team: a.team.trim().toLowerCase() === 'true' }\n    // Agent Teams live in Harness itself; a plugin without the team feature would drop it silently.\n    if (a.team != null) {\n      if (!host) throw new Error('Agent Teams need the dsh-baton-host plugin running inside DeepSeek Harness. Nothing was sent.')\n      if (!hostFeatures.includes('team')) throw new Error(`The Harness plugin dsh-baton-host ${hostVersion} is too old to turn on Agent Teams; this MCP server is ${VERSION}. Nothing was sent. Update the plugin (Plugins → dsh-baton-host → Update to ${VERSION}), or send without team.`)\n    }\n    // No Harness CLI to run the turn without the app (the Windows app has none on PATH): what\n    // is wrong is that Harness is not running, not that a CLI is missing.\n    if (!host) { try { dshBin() } catch { throw new Error('DeepSeek Harness is not running, or its dsh-baton-host plugin is switched off: open Harness (Plugins → dsh-baton-host on) and send again.') } }\n    const st = host ? tag('host', await hostCall('send', a)) : tag('headless', await waitForSessionId(startRun(a)))\n    evidence.prepare(config.batonHome, { run_id: st.run_id, session_id: st.session_id, cwd: await runFolder(a, st), checks })\n    return st\n  },\n  async status({ run_id, session_id, tail = 20 }) {\n    if (!run_id && session_id) {\n      if (!(await useHost())) throw new Error('A session\\'s status needs the dsh-baton-host plugin running inside DeepSeek Harness.')\n      return shaped(await hostCall('status', { session_id }).catch(tooOld('status', 'look at a session by its id')))\n    }\n    if (!run_id) throw new Error('run_id or session_id is required')\n    return withEvidence(shaped(isHostRun(run_id) ? tag('host', await hostCall('status', { run_id, tail })) : tag('headless', runStatus(run_id, { tail }))))\n  },\n  // Wait on a session's Harness goal without sending anything (host follow()); a report that\n  // has rounds in it also lists the files changed in the session's folder since the last one.\n  async follow({ session_id, until = 'goal', cursor, since_ms, every_s = 600, timeout_s = 300 }) {\n    if (!session_id) throw new Error('session_id is required')\n    if (!(await useHost())) throw new Error('Following a session needs the dsh-baton-host plugin running inside DeepSeek Harness.')\n    const st = shaped(await hostCall('follow', { session_id, until, cursor, ...(since_ms ? { since_ms } : {}), every_s, timeout_s }, { timeoutMs: (timeout_s + 15) * 1000 }).catch(tooOld('follow', 'follow a goal')))\n    // An older plugin's timed-out call still carries the rounds: they come with the report.\n    if (st.timed_out && Array.isArray(st.rounds)) {\n      const { rounds, earlier_rounds_not_shown: earlier = 0, ...rest } = st\n      return { ...rest, rounds_since_report: rounds.length + earlier }\n    }\n    if (st.timed_out) return st\n    if (st.state === 'no_goal' || !st.cwd) return st\n    const changed = evidence.changedSince(st.cwd, Date.parse(st.since) || 0)\n    return changed ? { ...st, changed_files: changed } : st\n  },\n  async wait({ run_id, timeout_s = 300 }) {\n    if (!isHostRun(run_id)) return withEvidence(tag('headless', await waitRun(run_id, { timeout_s })))\n    // Harness quit or restarting: wait for it to come back within the same call (the plugin then\n    // reports the run as interrupted) instead of failing, which had Codex retry every few seconds.\n    const deadline = Date.now() + timeout_s * 1000\n    for (;;) {\n      const left = Math.max(1, Math.ceil((deadline - Date.now()) / 1000))\n      try {\n        return withEvidence(shaped(tag('host', await hostCall('wait', { run_id, timeout_s: left }, { timeoutMs: (left + 15) * 1000 }))))\n      } catch (error) {\n        if (!(error?.hostDown || error?.hostClosed)) throw error\n        if (Date.now() + HOST_RETRY_MS >= deadline) return { run_id, state: 'unknown', timed_out: true, harness_down: true, backend: 'host' }\n        await new Promise((r) => setTimeout(r, HOST_RETRY_MS))\n      }\n    }\n  },\n  async cancel({ run_id, session_id }) {\n    if (run_id && !isHostRun(run_id)) return tag('headless', cancelRun(run_id))\n    return tag('host', await hostCall('cancel', { run_id, session_id }, { timeoutMs: 40000 }))\n  },\n  async rename_session(a) {\n    if (!(await useHost())) throw new Error('Renaming needs the dsh-baton-host plugin running inside DeepSeek Harness.')\n    return hostCall('rename_session', a)\n  },\n  async rename_workspace(a) {\n    if (!(await useHost())) throw new Error('Renaming needs the dsh-baton-host plugin running inside DeepSeek Harness.')\n    return hostCall('rename_workspace', a)\n  },\n  async activity({ session_id }) {\n    if (!(await useHost())) throw new Error('Session activity needs the dsh-baton-host plugin running inside DeepSeek Harness.')\n    return hostCall('activity', { session_id })\n  },\n  async update_queued(a) {\n    if (!(await useHost())) throw new Error('Changing a queued message needs the dsh-baton-host plugin running inside DeepSeek Harness.')\n    try {\n      return await hostCall('update_queued', a)\n    } catch (error) {\n      if (!/Unknown method: update_queued/.test(error?.message)) throw error\n      throw new Error(`The Harness plugin dsh-baton-host ${hostVersion ?? ''} is too old to change queued messages; this MCP server is ${VERSION}. Update the plugin in Harness: Plugins → dsh-baton-host → Uninstall, then Add plugin → dsh-baton-host@${VERSION}.`.replace('  ', ' '))\n    }\n  },\n  // reason (why the client chose, when the user let it decide) stays here: it is for the\n  // user, not for Harness.\n  async answer({ reason, ...a }) {\n    if (!(await useHost())) throw new Error('Answering a question needs the dsh-baton-host plugin running inside DeepSeek Harness.')\n    const check = optionCheck(a, reason)\n    if (check) return check\n    try {\n      const result = shaped(await hostCall('answer', a))\n      if (!(typeof reason === 'string' && reason.trim())) return result\n      if (result.submitted && a.run_id) rememberReason(a.run_id, result.answers, reason.trim())\n      return { ...result, reason: reason.trim() }\n    } catch (error) {\n      if (!/Unknown method: answer/.test(error?.message)) throw error\n      throw new Error(`The Harness plugin dsh-baton-host ${hostVersion ?? ''} is too old to answer questions; this MCP server is ${VERSION}. Answer in the Harness window, or update the plugin: Plugins → dsh-baton-host → Uninstall, then Add plugin → dsh-baton-host@${VERSION}.`.replace('  ', ' '))\n    }\n  },\n  async list_runs({ limit = 10, session_id } = {}) {\n    // An older plugin ignores session_id, so the host's runs are filtered here too.\n    const host = (await hostAvailable()) ? tag('host', await hostCall('list_runs', { limit: session_id ? 100 : limit, session_id })).filter((r) => !session_id || r.session_id === session_id) : []\n    return [...host, ...tag('headless', listRuns({ limit, session_id }))].sort((x, y) => String(y.started_at).localeCompare(String(x.started_at))).slice(0, limit).map(shaped)\n  },\n}\n"
